# egyptround7.py: round 7's sections of egypt_themes.html (all built into the game): the plain prince, the tomb robbers, the barque
# clock (an invented Egyptian timekeeper, with two other concepts), the glass jars, the faience hearts, the panels. Pictures from egyptr7.py.
import html
E = html.escape


def links(src):
    return '<ul>' + ''.join('<li><a href="%s">%s</a></li>' % (E(u), E(l)) for l, u in src) + '</ul>'


def fig(img, f, cap):
    return '<figure>%s<figcaption>%s</figcaption></figure>' % (img(f, cap), E(cap))


def sections(D, REL, img):
    o = []
    o.append('<section class="card" id="r7prince"><h2>Round 7: the prince in plain linen (superseded by round 8)</h2><p>Owner: "The prince should not be in full prince gear. Should be something like the original prince, I like that style." He is the original figure again (its proportions, flat colours, hair and read), Egyptian only in a few plain things: '
             'a short tunic and a kilt of undyed white linen, bare feet, his own hair, the orange sash as the one accent, and the straight blade in bronze (the straight sword of the New Kingdom; the khopesh fought the original\'s look). '
             '<b>Based on:</b> the everyday dress of ordinary young Egyptian men, a linen kilt and, from the New Kingdom, a short tunic over it, mostly barefoot; close to Prince of Persia\'s white-clad hero. Same skeleton, poses, hit boxes and timing; the bot unchanged; the figures\' mask and the beams\' figure light from his outline.</p>' +
             links([('Clothing in ancient Egypt (the kilt, the tunic, going barefoot)', 'https://en.wikipedia.org/wiki/Clothing_in_ancient_Egypt'), ('Shendyt', 'https://en.wikipedia.org/wiki/Shendyt'), ('The Met: a linen kerchief from Tutankhamun\'s embalming cache (a plain head cloth)', 'https://www.metmuseum.org/toah/works-of-art/09.184.218')]) +
             '<p class="meta">(Its pictures, the comparison sheet and the running GIF, were retired in round 17 to keep the page under its file cap; round 8 and later show the prince as he is.)</p></section>')
    o.append('<section class="card" id="robbers"><h2>The guards: tomb robbers (built in)</h2><p>In the same plain style: kilts of undyed linen, bare chests and feet; the recruit (ochre) and the soldier (green) in head cloths of their colour, the veteran in a crimson short tunic and a leather cap, the captain in a leather corselet and cap with a violet sash. '
             'Weapons by tier: a club, an axe, an axe, a khopesh, drawn along the sword\'s line and length, so their fighting, reach and timing are unchanged. The skeletons stay. Their shadows and masks use the robbers\' outline (<code>PAL_GSIL</code>). '
             '<b>Based on:</b> the robbers named in the tomb-robbery papyri of the late 20th Dynasty were the necropolis\'s own workmen, stonecutters, priests and minor officials; workmen wore kilts and head cloths (a plain linen kerchief survives from Tutankhamun\'s embalming cache); soldiers wore leather caps and corselets.</p>' +
             links([('Abbott Papyrus: the tomb robberies under Ramesses IX', 'https://en.wikipedia.org/wiki/Abbott_Papyrus'), ('Ismaeel, notes on the Abbott Papyrus (state employees complicit)', 'https://bcps.journals.ekb.eg/article_267954.html?lang=en'), ('Deir el-Medina, the workmen\'s village', 'https://en.wikipedia.org/wiki/Deir_el-Medina'), ('Ancient Egyptian weapons: axes, maces, khopesh', 'https://en.wikipedia.org/wiki/Military_of_ancient_Egypt')]) +
             fig(img, 'r7_robbers.png', 'Recruit, soldier, veteran, captain') +
             '<div class="g2" style="margin-top:8px">%s%s</div></section>' % (fig(img, 'r7_fight_1.gif', 'The prince against the soldier (axe)'), fig(img, 'r7_fight_3.gif', 'Against the captain (khopesh)')))
    o.append('<section class="card" id="barque"><h2>Superseded: the barque clock (round 7)</h2><p><b>Rejected by the owner in round 8:</b> "As for the hourglass, anything that looks like a water glass or a hourglass is rejected by default." A bowl over a basin joined by a stream reads as a vessel; replaced by the sky clock (above). As it was proposed: Owner: "Those water clocks look like water glasses. Let\'s invent an Egyptian hour glass that is unique." Three concepts, each at HUD and gate-clock size; '
             'A was built in for round 7.</p><ul>'
             '<li><b>A, the barque clock.</b> An open lotus bowl of calcite over a lower basin, joined by a glowing stream, between two djed-pillar uprights; on the water in the bowl rides the sun\'s barque with its disc, and as the hour runs out it sinks with the water, as the sun\'s boat goes down through the twelve hours of night in the Amduat (the story of Dawnward). The bowl\'s side carries the hour marks of the Karnak clepsydra. It reads as time running out at a glance: top full, draining into the bottom, the gold sun going down. In the rewind the water flows back up, the barque rising, under the cool tint.</li>'
             '<li><b>B, Thoth\'s baboon.</b> The baboon of Thoth, lord of time, sits on the vessel with the moon disc and the water runs from beneath him, as the Karnak clepsydra\'s spout sat below a baboon on a djed pillar (Horapollo ties the baboon to the hours and the water clock). Distinctive, but a small figure is hard to read at HUD size.</li>'
             '<li><b>C, the sun\'s descent.</b> A was-sceptre column marked with twelve hours, down which the sun\'s disc travels. Clean, but it reads as a gauge rather than an hourglass.</li></ul>'
             '<p><b>Its light</b> (drawn in the shared 2D code as added light, so the same in both modes; no new pass, no clip, nothing per pixel jittered): a rim on the water and on the calcite\'s edge toward the nearest lamp (the key light the figures use), light through the falling stream, a soft glow inside the bowl and round the sun\'s disc, pulsing slowly so it reads as the timer. A still HUD clock does not animate, so the HUD canvas is redrawn only when it changes. Based on: water and calcite optics (a bright rim where light meets the surface at a grazing angle, light carried along a falling stream, translucent calcite lit from within).</p>' +
             links([('Egypt Museum: the clepsydra of Karnak', 'https://egypt-museum.com/clepsydra-of-karnak/'), ('McMaster Ancient Egyptian Astronomy: the water clock of Amenhotep III (baboon, hour scales, decans)', 'https://aea.mcmaster.ca/index.php/en/database/ars/ar1-type-menu/water-clock-amenhotep-iii'),
                    ('Amduat: the sun\'s barque through the twelve hours', 'https://en.wikipedia.org/wiki/Amduat'), ('Djed', 'https://en.wikipedia.org/wiki/Djed'), ('Was-sceptre', 'https://en.wikipedia.org/wiki/Was-sceptre'), ('Hieroglyphica of Horapollo (the baboon and the hours)', 'https://en.wikipedia.org/wiki/Hieroglyphica')]))
    for k, nm in (('A', 'A, the barque clock (round 7, rejected)'), ('B', 'B, Thoth\'s baboon'), ('C', 'C, the sun\'s descent')):
        # (retired to keep the page under its file cap: the rejected concepts' half and nearly-out frames and their running GIF)
        o.append('<h3>%s</h3><p class="meta">(Its pictures are retired to keep the page under its file cap; the design was rejected.)</p>' % E(nm))  # (rounds 13 to 15)
    o.append('<p class="meta">(The rejected clock\'s checkpoint pictures were retired in round 16a to keep the page under its file cap; round 25d: its HUD, r7_hud.png, too, superseded by round 8\'s.)</p></section>')
    o.append('<section class="card" id="jars"><h2>Glass jars (round 7; superseded by round 9\'s Egyptian flasks)</h2><p>The flasks are Egyptian core-formed glass: translucent blue glass wound with yellow and white trails combed into zigzags and feathers, one shape to a kind: a krateriskos (a small bowl on a foot) for the small heal, an amphoriskos with two handles for the large, the Amarna fish bottle for the extra life, a dark alabastron for poison. '
             'The liquid\'s colour, level, tilt, bubbles and glow show through as before, at the same size and pickup box. <b>Based on:</b> 18th Dynasty core-formed glass vessels.</p>' +
             links([('British Museum: glass fish-shaped bottle from Amarna (EA 55193)', 'https://www.britishmuseum.org/collection/object/Y_EA55193'), ('The Met: core-formed spindle bottle, Amarna', 'https://www.metmuseum.org/art/collection/search/544861'), ('Toledo Museum of Art: core-formed amphoriskos, Dynasty 18', 'https://emuseum.toledomuseum.org/objects/57880/cosmetic-jar-amphoriskos'), ('V&A: core-formed unguent jar', 'https://collections.vam.ac.uk/item/O20'), ('Core-forming (the technique, the combed trails)', 'https://en.wikipedia.org/wiki/Core-forming')]) +
             '<p class="meta">(Its pictures were retired in round 16a to keep the page under its file cap: the jars are superseded by round 9\'s flasks.)</p></section>')
    o.append('<section class="card" id="hearts"><h2>Faience hearts and the panels (built in)</h2><p>Each life is an <i>ib</i> heart amulet in blue-green faience (a vessel-shaped heart with a rim and two lugs), dark and empty when lost; the guards\' health uses the same shape in their tier\'s colour. No ankhs. '
             'The title and pause panels get one thin cavetto cornice over a torus moulding at their head, nothing else; Rokkitt and Jost unchanged. <b>Based on:</b> heart amulets (ib) of faience and stone; the cavetto cornice and torus that crown Egyptian doorways and shrines.</p>' +
             links([('The Met: faience heart amulet of Isetweret', 'https://www.metmuseum.org/art/collection/search/577179'), ('The Met: Egyptian amulets (the heart at the weighing)', 'https://www.metmuseum.org/essays/egyptian-amulets'), ('Ib (the heart)', 'https://en.wikipedia.org/wiki/Ib_(Egyptian_heart)'), ('Cavetto (the Egyptian cornice)', 'https://en.wikipedia.org/wiki/Cavetto')]) +
             '<div class="g4">%s%s%s</div></section>' % (fig(img, 'r7_hearts.png', 'Four lives left of six'), fig(img, 'r7_title.jpg', 'Title'), fig(img, 'r7_pause.jpg', 'Pause')))
    return o, [('r7prince', 'Plain prince'), ('robbers', 'Robbers'), ('barque', 'Barque clock'), ('jars', 'Jars'), ('hearts', 'Hearts, panels')]
